/**
 * Remove scaffold example files from the slack-api skill and prune the
 * now-empty assets directory, so validation (no TODOs) passes and the
 * package contains only real content.
 */

const fs = require('node:fs');
const path = require('node:path');

const skillDir = path.join(__dirname, '..', 'slack-api');

const targets = [
  path.join(skillDir, 'scripts', 'example_script.js'),
  path.join(skillDir, 'references', 'example_reference.md'),
  path.join(skillDir, 'assets', 'example_asset.txt'),
];

for (const t of targets) {
