    console.log('No replies found.');
    return;
  }
  for (const m of data.messages) {
    const user = m.user || m.bot_id || '?';
    const marker = m.ts === opts.thread_ts ? ' (parent)' : '';
    console.log(`${m.ts} <${user}>${marker} ${summarizeText(m.text)}`);
  }
}

async function cmdAddReaction(opts) {
  const token = getToken();
