#!/usr/bin/env node

/**
 * slack_api.js — helper for the Slack Web API
 *
 * Usage:
 *   node scripts/slack_api.js <command> [options]
 *
 * Requires Node.js 18+ (global fetch / FormData / Blob). Reads the token
 * from the SLACK_TOKEN environment variable (SLACK_BOT_TOKEN as fallback).
 *
 * Agentic ergonomics: no stack traces; a single clean "Failure: ..." line
 * on error; summaries are truncated to stay LLM-friendly; --json prints
 * the raw API response when structured data is needed.
 */

'use strict';

const fs = require('node:fs');
const path = require('node:path');

const API_BASE = 'https://slack.com/api/';

const USAGE = `Usage: node scripts/slack_api.js <command> [options]

Commands:
  send-message      Post a message (optionally as a thread reply)
  list-channels     List public/private channels
  channel-history   Fetch recent messages from a channel
  thread-replies    Fetch replies in a thread
  add-reaction      Add an emoji reaction to a message
  remove-reaction   Remove an emoji reaction from a message
  upload-file       Upload a file to a channel
  list-users        List workspace users
  user-info         Get details for a user

Options:
  --channel <name or id>  Channel name (general or #general) or ID (C...)
  --text <text>           Message text (Slack mrkdwn allowed)
  --blocks <json>         Slack blocks payload (send-message)
  --thread-ts <ts>        Parent message timestamp (thread reply)
  --timestamp <ts>        Message timestamp (reactions)
  --emoji <name>          Emoji name without colons, e.g. white_check_mark
  --file <path>           Local file path (upload-file)
  --filename <name>       Uploaded filename (default: basename of --file)
  --title <title>         File title (upload-file)
  --initial-comment <text>  Message posted with the file (upload-file)
  --limit <n>             Max items to fetch (default: 10 history, 100 lists)
  --types <list>          Channel types for list-channels
                          (default: public_channel,private_channel)
  --include-archived      Include archived channels in list-channels
  --oldest <ts>           Only messages after this timestamp (channel-history)
  --latest <ts>           Only messages before this timestamp (channel-history)
  --cursor <cursor>       Pagination cursor for list calls
  --user <id>             User ID (user-info)
  --json                  Print the raw JSON response instead of a summary

Environment:
  SLACK_TOKEN      Slack token (bot or user). SLACK_BOT_TOKEN is used as a fallback.

Examples:
  node scripts/slack_api.js send-message --channel general --text "Hello!"
  node scripts/slack_api.js channel-history --channel general --limit 10
  node scripts/slack_api.js add-reaction --channel general --timestamp 1710000000.123456 --emoji white_check_mark
`;

const ERROR_HINTS = {
  not_authed: 'missing or invalid token',
  invalid_auth: 'token is invalid or revoked',
  account_inactive: 'the token owner account is inactive',
  token_revoked: 'the token has been revoked',
  missing_scope: 'token lacks a required scope - see references/slack-api.md',
  invalid_arguments: 'invalid arguments passed to the API',
  channel_not_found: 'channel not found - check the ID/name and that the bot can access it',
  is_archived: 'channel is archived - unarchive it first',
  not_in_channel: 'bot is not in the channel - invite it first',
  user_not_in_channel: 'user is not in the channel',
  invalid_emoji: 'emoji name is not valid in this workspace',
  too_many_attachments: 'too many attachments in one message',
  msg_too_long: 'message text exceeds 40000 characters',
  invalid_blocks: 'blocks payload is malformed',
  rate_limited: 'rate limit hit - back off and retry',
  internal_error: 'Slack-side error - retry with backoff',
  user_not_found: 'user ID not found',
  file_not_found: 'file not found or inaccessible',
  not_authorized: 'token lacks authorization for this action',
  restricted_action: 'workspace policy restricts this action',
  team_access_needed: 'app is not installed in this workspace',
};

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function parseArgs(argv) {
  const opts = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        opts[arg.slice(2, eq)] = arg.slice(eq + 1);
        continue;
      }
      const key = arg.slice(2);
      const next = argv[i + 1];
      if (next !== undefined && !next.startsWith('--')) {
        opts[key] = next;
        i++;
      } else {
        opts[key] = true;
      }
    } else {
      opts._.push(arg);
    }
  }
  return opts;
}

function getToken() {
  const cred = process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN;
  if (!cred) {
    fail('SLACK_TOKEN is not set. Export it before calling the API.');
  }
  return cred;
}

function parseLimit(value, def) {
  if (value === undefined) return def;
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1 || n > 1000) {
    fail(`Invalid --limit "${value}" (expected an integer between 1 and 1000).`);
  }
  return n;
}

async function parseResponse(res, method) {
  if (res.status === 429) {
    const retryAfter = Number(res.headers.get('Retry-After') || 1);
    fail(
      `Rate limited by Slack (${method}). Retry after ${retryAfter}s, or reduce --limit for large reads.`,
    );
  }
  if (!res.ok) {
    fail(`HTTP ${res.status} from Slack API (${method}).`);
  }
  let data;
  try {
    data = await res.json();
  } catch (err) {
    fail(`Invalid JSON response from Slack API (${method}).`);
  }
  if (!data.ok) {
    const hint = ERROR_HINTS[data.error];
    fail(
      `Slack API error (${method}): ${data.error}${hint ? ` - ${hint}` : ''}`,
    );
  }
  return data;
}

async function apiCall(token, method, params, form = false) {
  let res;
  if (form) {
    const body = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null) body.set(k, String(v));
    }
    try {
      res = await fetch(new URL(method, API_BASE), {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body,
      });
    } catch (err) {
      fail(`Network error calling ${method}: ${err.message}`);
    }
  } else {
    const url = new URL(method, API_BASE);
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null) url.searchParams.set(k, String(v));
    }
    try {
      res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
    } catch (err) {
      fail(`Network error calling ${method}: ${err.message}`);
    }
  }
  return parseResponse(res, method);
}

async function resolveChannel(token, channel) {
  if (!channel) fail('Missing --channel (channel name or ID).');
  if (/^[CDG][A-Z0-9]{8,}$/.test(channel)) return channel;
  const name = channel.replace(/^#/, '');
  const data = await apiCall(token, 'conversations.list', {
    types: 'public_channel,private_channel',
    limit: 200,
  });
  const match = data.channels.find((c) => c.name === name);
  if (!match) {
    fail(
      `Channel "${name}" not found. Check the name, or pass the channel ID (C...) instead.`,
    );
  }
  return match.id;
}

function summarizeText(text) {
  return String(text || '').replace(/\s+/g, ' ').slice(0, 200);
}

async function cmdSendMessage(opts) {
  const token = getToken();
  const channel = await resolveChannel(token, opts.channel);
  if (!opts.text && !opts.blocks) {
    fail('Provide --text and/or --blocks for the message.');
  }
  const params = { channel, text: opts.text || '' };
  if (opts.thread_ts) params.thread_ts = opts.thread_ts;
  if (opts.blocks) {
    try {
      params.blocks = JSON.stringify(JSON.parse(opts.blocks));
    } catch (err) {
      fail('--blocks must be valid JSON (e.g. {"blocks":[...]}).');
    }
  }
  const data = await apiCall(token, 'chat.postMessage', params, true);
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  const where = data.channel ? `#${data.channel}` : channel;
  const thread = data.thread_ts ? ` (thread ts=${data.thread_ts})` : '';
  console.log(`Sent to ${where} ts=${data.ts}${thread}`);
}

async function cmdListChannels(opts) {
  const token = getToken();
  const data = await apiCall(token, 'conversations.list', {
    types: opts.types || 'public_channel,private_channel',
    exclude_archived: opts.include_archived ? 'false' : 'true',
    limit: parseLimit(opts.limit, 100),
    cursor: opts.cursor,
  });
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  for (const c of data.channels) {
    const flags = [
      c.is_private ? 'private' : null,
      c.is_archived ? 'archived' : null,
      c.is_member ? 'member' : null,
    ]
      .filter(Boolean)
      .join(',');
    console.log(`${c.id}  #${c.name}${flags ? ` (${flags})` : ''}`);
  }
  const next = data.response_metadata && data.response_metadata.next_cursor;
  if (next) {
    console.log(`(more results: pass --cursor ${next})`);
  }
}

async function cmdChannelHistory(opts) {
  const token = getToken();
  const channel = await resolveChannel(token, opts.channel);
  const data = await apiCall(token, 'conversations.history', {
    channel,
    limit: parseLimit(opts.limit, 10),
    latest: opts.latest,
    oldest: opts.oldest,
  });
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  if (!data.messages.length) {
    console.log('No messages found.');
    return;
  }
  for (const m of data.messages) {
    const user = m.user || m.bot_id || '?';
    const thread = m.thread_ts ? ` [thread replies=${m.reply_count || 0}]` : '';
    console.log(`${m.ts} <${user}>${thread} ${summarizeText(m.text)}`);
  }
  if (data.has_more) {
    const last = data.messages[data.messages.length - 1].ts;
    console.log(`(more messages available: pass --oldest ${last} to continue)`);
  }
}

async function cmdThreadReplies(opts) {
  const token = getToken();
  if (!opts.thread_ts) fail('Missing --thread-ts <parent message ts>.');
  const channel = await resolveChannel(token, opts.channel);
  const data = await apiCall(token, 'conversations.replies', {
    channel,
    ts: opts.thread_ts,
    limit: parseLimit(opts.limit, 10),
  });
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  if (!data.messages.length) {
    console.log('No replies found.');
    return;
  }
  for (const m of data.messages) {
    const user = m.user || m.bot_id || '?';
    const marker = m.ts === opts.thread_ts ? ' (parent)' : '';
    console.log(`${m.ts} <${user}>${marker} ${summarizeText(m.text)}`);
  }
}

async function cmdAddReaction(opts) {
  const token = getToken();
  const channel = await resolveChannel(token, opts.channel);
  if (!opts.timestamp) fail('Missing --timestamp <message ts>.');
  if (!opts.emoji) fail('Missing --emoji <name> (no colons, e.g. white_check_mark).');
  const data = await apiCall(
    token,
    'reactions.add',
    { channel, timestamp: opts.timestamp, name: opts.emoji },
    true,
  );
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  console.log(`Added :${opts.emoji}: to message ${opts.timestamp} in ${channel}`);
}

async function cmdRemoveReaction(opts) {
  const token = getToken();
  const channel = await resolveChannel(token, opts.channel);
  if (!opts.timestamp) fail('Missing --timestamp <message ts>.');
  if (!opts.emoji) fail('Missing --emoji <name> (no colons, e.g. white_check_mark).');
  const data = await apiCall(
    token,
    'reactions.remove',
    { channel, timestamp: opts.timestamp, name: opts.emoji },
    true,
  );
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  console.log(`Removed :${opts.emoji}: from message ${opts.timestamp} in ${channel}`);
}

async function cmdUploadFile(opts) {
  const token = getToken();
  if (!opts.file) fail('Missing --file <path>.');
  if (typeof FormData === 'undefined' || typeof Blob === 'undefined') {
    fail('upload-file needs Node.js 18+ (FormData/Blob globals).');
  }
  let buffer;
  try {
    buffer = fs.readFileSync(opts.file);
  } catch (err) {
    fail(`Cannot read file "${opts.file}": ${err.message}`);
  }
  const channel = opts.channel
    ? await resolveChannel(token, opts.channel)
    : null;
  const form = new FormData();
  form.append(
    'file',
    new Blob([buffer]),
    opts.filename || path.basename(opts.file),
  );
  if (channel) form.append('channels', channel);
  if (opts.title) form.append('title', opts.title);
  if (opts.initial_comment) form.append('initial_comment', opts.initial_comment);

  let res;
  try {
    res = await fetch(new URL('files.upload', API_BASE), {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: form,
    });
  } catch (err) {
    fail(`Network error calling files.upload: ${err.message}`);
  }
  const data = await parseResponse(res, 'files.upload');
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  const f = data.file || {};
  const target = f.channels ? f.channels : channel || '(not shared)';
  console.log(
    `Uploaded "${f.name || opts.filename}" to ${target} id=${f.id}${
      f.permalink ? ` permalink=${f.permalink}` : ''
    }`,
  );
}

async function cmdListUsers(opts) {
  const token = getToken();
  const data = await apiCall(token, 'users.list', {
    limit: parseLimit(opts.limit, 100),
    cursor: opts.cursor,
  });
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  for (const u of data.members) {
    const name = u.real_name || u.name || '?';
    const flags = [
      u.deleted ? 'deleted' : null,
      u.is_bot ? 'bot' : null,
    ]
      .filter(Boolean)
      .join(',');
    console.log(`${u.id}  ${name}${flags ? ` (${flags})` : ''}`);
  }
  const next = data.response_metadata && data.response_metadata.next_cursor;
  if (next) {
    console.log(`(more results: pass --cursor ${next})`);
  }
}

async function cmdUserInfo(opts) {
  const token = getToken();
  if (!opts.user) fail('Missing --user <user ID> (e.g. U123ABC).');
  const data = await apiCall(token, 'users.info', { user: opts.user });
  if (opts.json) {
    console.log(JSON.stringify(data));
    return;
  }
  const u = data.user || {};
  console.log(
    `id=${u.id} name=${u.name || '?'} real_name=${u.real_name || '?'}${
      u.profile && u.profile.email ? ` email=${u.profile.email}` : ''
    }${u.is_bot ? ' (bot)' : ''}${u.deleted ? ' (deleted)' : ''}`,
  );
}

async function main() {
  const argv = process.argv.slice(2);
  if (
    argv.length === 0 ||
    argv[0] === 'help' ||
    argv[0] === '--help' ||
    argv[0] === '-h'
  ) {
    process.stdout.write(USAGE);
    return;
  }
  const opts = parseArgs(argv);
  if (opts.help) {
    process.stdout.write(USAGE);
    return;
  }
  const command = opts._[0];
  switch (command) {
    case 'send-message':
      return cmdSendMessage(opts);
    case 'list-channels':
      return cmdListChannels(opts);
    case 'channel-history':
      return cmdChannelHistory(opts);
    case 'thread-replies':
      return cmdThreadReplies(opts);
    case 'add-reaction':
      return cmdAddReaction(opts);
    case 'remove-reaction':
      return cmdRemoveReaction(opts);
    case 'upload-file':
      return cmdUploadFile(opts);
    case 'list-users':
      return cmdListUsers(opts);
    case 'user-info':
      return cmdUserInfo(opts);
    default:
      fail(
        `Unknown command "${command}". Run without arguments to see usage.`,
      );
  }
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node

/* eslint-env node */

/**
 * Skill Initializer - Creates a new skill from template
 *
 * Usage:
 *     node init_skill.cjs <skill-name> --path <path>
 *
 * Examples:
 *     node init_skill.cjs my-new-skill --path skills/public
 */

const fs = require('node:fs');
const path = require('node:path');

const SKILL_TEMPLATE = `---
name: {skill_name}
description: TODO: Complete and informative explanation of what the skill does and when to use it. Include WHEN to use this skill - specific scenarios, file types, or tasks that trigger it.
---

# {skill_title}

## Overview

[TODO: 1-2 sentences explaining what this skill enables]

## Structuring This Skill

[TODO: Choose the structure that best fits this skill's purpose. Common patterns:

**1. Workflow-Based** (best for sequential processes)
- Works well when there are clear step-by-step procedures
- Example: CSV-Processor skill with "Workflow Decision Tree" → "Ingestion" → "Cleaning" → "Analysis"
- Structure: ## Overview → ## Workflow Decision Tree → ## Step 1 → ## Step 2...

**2. Task-Based** (best for tool collections)
- Works well when the skill offers different operations/capabilities
- Example: PDF skill with "Quick Start" → "Merge PDFs" → "Split PDFs" → "Extract Text"
- Structure: ## Overview → ## Quick Start → ## Task Category 1 → ## Task Category 2...

**3. Reference/Guidelines** (best for standards or specifications)
- Works well for brand guidelines, coding standards, or requirements
- Example: Brand styling with "Brand Guidelines" → "Colors" → "Typography" → "Features"
- Structure: ## Overview → ## Guidelines → ## Specifications → ## Usage...

**4. Capabilities-Based** (best for integrated systems)
- Works well when the skill provides multiple interrelated features
- Example: Product Management with "Core Capabilities" → numbered capability list
- Structure: ## Overview → ## Core Capabilities → ### 1. Feature → ### 2. Feature...

Patterns can be mixed and matched as needed. Most skills combine patterns (e.g., start with task-based, add workflow for complex operations).

Delete this entire "Structuring This Skill" section when done - it's just guidance.]

## [TODO: Replace with the first main section based on chosen structure]

[TODO: Add content here. See examples in existing skills:
- Code samples for technical skills
- Decision trees for complex workflows
- Concrete examples with realistic user requests
- References to scripts/templates/references as needed]

## Resources

This skill includes example resource directories that demonstrate how to organize different types of bundled resources:

### scripts/
Executable code that can be run directly to perform specific operations.

**Examples from other skills:**
- PDF skill: fill_fillable_fields.cjs, extract_form_field_info.cjs - utilities for PDF manipulation
- CSV skill: normalize_schema.cjs, merge_datasets.cjs - utilities for tabular data manipulation

**Appropriate for:** Node.cjs scripts (cjs), shell scripts, or any executable code that performs automation, data processing, or specific operations.

**Note:** Scripts may be executed without loading into context, but can still be read by Gemini CLI for patching or environment adjustments.

### references/
Documentation and reference material intended to be loaded into context to inform Gemini CLI's process and thinking.

**Examples from other skills:**
- Product management: communication.md, context_building.md - detailed workflow guides
- BigQuery: API reference documentation and query examples
- Finance: Schema documentation, company policies

**Appropriate for:** In-depth documentation, API references, database schemas, comprehensive guides, or any detailed information that Gemini CLI should reference while working.

### assets/
Files not intended to be loaded into context, but rather used within the output Gemini CLI produces.

**Examples from other skills:**
- Brand styling: PowerPoint template files (.pptx), logo files
- Frontend builder: HTML/React boilerplate project directories
- Typography: Font files (.ttf, .woff2)

**Appropriate for:** Templates, boilerplate code, document templates, images, icons, fonts, or any files meant to be copied or used in the final output.

---

**Any unneeded directories can be deleted.** Not every skill requires all three types of resources.
`;

const EXAMPLE_SCRIPT = `#!/usr/bin/env node

/**
 * Example helper script for {skill_name}
 *
 * This is a placeholder script that can be executed directly.
 * Replace with actual implementation or delete if not needed.
 *
 * Example real scripts from other skills:
 * - pdf/scripts/fill_fillable_fields.cjs - Fills PDF form fields
 * - pdf/scripts/convert_pdf_to_images.cjs - Converts PDF pages to images
 *
 * Agentic Ergonomics:
 * - Suppress tracebacks.
 * - Return clean success/failure strings.
 * - Truncate long outputs.
 */

async function main() {
  try {
    // TODO: Add actual script logic here.
    // This could be data processing, file conversion, API calls, etc.

    // Example output formatting for an LLM agent
    process.stdout.write("Success: Processed the task.\\n");
  } catch (err) {
    // Trap the error and output a clean message instead of a noisy stack trace
    process.stderr.write(\`Failure: \${err.message}\\n\`);
    process.exit(1);
  }
}

main();
`;

const EXAMPLE_REFERENCE = `# Reference Documentation for {skill_title}

This is a placeholder for detailed reference documentation.
Replace with actual reference content or delete if not needed.

## Structure Suggestions

### API Reference Example
- Overview
- Authentication
- Endpoints with examples
- Error codes

### Workflow Guide Example
- Prerequisites
- Step-by-step instructions
- Best practices
`;

function titleCase(name) {
  return name
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 3 || args[1] !== '--path') {
    console.log('Usage: node init_skill.cjs <skill-name> --path <path>');
    process.exit(1);
  }

  const skillName = args[0];
  const basePath = path.resolve(args[2]);

  // Prevent path traversal
  if (
    skillName.includes(path.sep) ||
    skillName.includes('/') ||
    skillName.includes('\\')
  ) {
    console.error('❌ Error: Skill name cannot contain path separators.');
    process.exit(1);
  }

  const skillDir = path.join(basePath, skillName);

  // Additional check to ensure the resolved skillDir is actually inside basePath
  if (!skillDir.startsWith(basePath)) {
    console.error('❌ Error: Invalid skill name or path.');
    process.exit(1);
  }

  if (fs.existsSync(skillDir)) {
    console.error(`❌ Error: Skill directory already exists: ${skillDir}`);
    process.exit(1);
  }

  const skillTitle = titleCase(skillName);

  try {
    fs.mkdirSync(skillDir, { recursive: true });
    fs.mkdirSync(path.join(skillDir, 'scripts'));
    fs.mkdirSync(path.join(skillDir, 'references'));
    fs.mkdirSync(path.join(skillDir, 'assets'));

    fs.writeFileSync(
      path.join(skillDir, 'SKILL.md'),
      SKILL_TEMPLATE.replace(/{skill_name}/g, skillName).replace(
        /{skill_title}/g,
        skillTitle,
      ),
    );
    fs.writeFileSync(
      path.join(skillDir, 'scripts/example_script.cjs'),
      EXAMPLE_SCRIPT.replace(/{skill_name}/g, skillName),
      { mode: 0o755 },
    );
    fs.writeFileSync(
      path.join(skillDir, 'references/example_reference.md'),
      EXAMPLE_REFERENCE.replace(/{skill_title}/g, skillTitle),
    );
    fs.writeFileSync(
      path.join(skillDir, 'assets/example_asset.txt'),
      'Placeholder for assets.',
    );

    console.log(`✅ Skill '${skillName}' initialized at ${skillDir}`);
  } catch (err) {
    console.error(`❌ Error: ${err.message}`);
    process.exit(1);
  }
}

main();

